{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_0619bb484e5d2ea93c41064d", "claim_ids": ["claim_117a160ac4455f95df00b998", "claim_792cd3fecce66dea42d0f69d"], "query_ids": ["q_36"], "claims": [{"claim_id": "claim_117a160ac4455f95df00b998", "quote": "The Trump administration this past week confirmed plans to lower tariffs on certain products, including vehicles, to 15% from South Korea. A notice about the implementation of the trade deal was posted Wednesday on the Federal Register.", "url": "https://www.cnbc.com/2025/12/03/trump-south-korea-tariffs-vehicles-hyundai-gm.html", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "lower tariffs on certain products, including vehicles, to 15% from South Korea", "legal_authority": "Federal Register"}}, {"claim_id": "claim_792cd3fecce66dea42d0f69d", "quote": "U.S.-South Korea trade deal, reducing tariffs to 15% enables Hyundai to diversify exports and support suppliers.", "url": "https://www.cbtnews.com/hyundai-to-invest-86-5b-in-south-korea-after-us-tariff-cut", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai", "tariff_program": "U.S.-South Korea trade deal", "duty_rate": "15%"}}]}, {"pair_id": "conflict_56a04199a2c7cea2576742d9", "claim_ids": ["claim_5f8caf338c689621af3cc8f1", "claim_792cd3fecce66dea42d0f69d"], "query_ids": ["q_36"], "claims": [{"claim_id": "claim_5f8caf338c689621af3cc8f1", "quote": "The agreement cuts tariffs on South Korean autos exported to the United States from 25% to 15%, prompting Hyundai and its affiliate Kia Corp to expand domestic production and exports.", "url": "https://www.cbtnews.com/hyundai-to-invest-86-5b-in-south-korea-after-us-tariff-cut", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai", "duty_rate": "15%"}}, {"claim_id": "claim_792cd3fecce66dea42d0f69d", "quote": "U.S.-South Korea trade deal, reducing tariffs to 15% enables Hyundai to diversify exports and support suppliers.", "url": "https://www.cbtnews.com/hyundai-to-invest-86-5b-in-south-korea-after-us-tariff-cut", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai", "tariff_program": "U.S.-South Korea trade deal", "duty_rate": "15%"}}]}, {"pair_id": "conflict_1e55497a099a17cb17db6323", "claim_ids": ["claim_0afbc6d2945e12fe30b04349", "claim_dbc2cd7b24ee3b902df3124b"], "query_ids": ["q_360"], "claims": [{"claim_id": "claim_0afbc6d2945e12fe30b04349", "quote": "As of February 1, 2025, the United States reactivated Section 232 tariffs: - 25% on steel imports - 10% on aluminum imports", "url": "https://www.ilscompany.com/automotive-tariffs-mexico-us", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232", "duty_rate": "25%", "effective_date": "February 1, 2025"}}, {"claim_id": "claim_dbc2cd7b24ee3b902df3124b", "quote": "Effective June 4, 2025, the Section 232 tariff on metal content doubled to 50%, applying across almost all steel and aluminum imports—including those from Mexico.", "url": "https://www.prodensa.com/insights/blog/how-tariffs-are-shaping-automotive-manufacturers-in-mexico", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232", "duty_rate": "50%", "effective_date": "June 4, 2025"}}]}, {"pair_id": "conflict_4e0be4a81e051cadbfc9fed4", "claim_ids": ["claim_0e63a116e33c3628da158714", "claim_f0af0e583aded5831280925f"], "query_ids": ["q_360"], "claims": [{"claim_id": "claim_0e63a116e33c3628da158714", "quote": "The US Department of Commerce opened a process to reduce Section 232 tariffs on eligible steel and aluminum imports from Mexico and Canada, linking relief to USMCA compliance and commitments to expand US production capacity.", "url": "https://mexicobusiness.news/mining/news/us-opens-path-cut-mexicos-steel-aluminum-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232"}}, {"claim_id": "claim_f0af0e583aded5831280925f", "quote": "Under the mechanism, the US Department of Commerce may reduce steel and aluminum tariffs by up to half the otherwise applicable rate. However, the adjusted rate cannot fall below 25%.", "url": "https://mexicobusiness.news/mining/news/us-opens-path-cut-mexicos-steel-aluminum-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "up to half the otherwise applicable rate"}}]}, {"pair_id": "conflict_9b900abc99121a3fc11e4da0", "claim_ids": ["claim_2b252561813bc732fd498051", "claim_a9ad09d8744db7d324739d67"], "query_ids": ["q_361"], "claims": [{"claim_id": "claim_2b252561813bc732fd498051", "quote": "Starting March 12, 2025, imports of Canadian steel and aluminum products into the United States could face tariffs that exceed 25%, if the proposed 25% tariff on imported goods under the US International Emergency Economic Powers Act (IEEPA) is also implemented.", "url": "https://www.pwc.com/ca/en/services/tax/publications/tax-insights/us-impose-tariffs-steel-aluminum-imports-2025.html", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "US International Emergency Economic Powers Act (IEEPA)", "effective_date": "March 12, 2025"}}, {"claim_id": "claim_a9ad09d8744db7d324739d67", "quote": "U.S. presidential proclamations “Adjusting Imports of Steel Into the United States” and “Adjusting Imports of Aluminum Into the United States” dated February 10, 2025, impose a 25% tariff on steel and aluminum imported from all countries effective March 12, 2025.", "url": "https://www.jdsupra.com/legalnews/u-s-canada-tariffs-timeline-of-key-1897320", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Adjusting Imports of Steel Into the United States", "duty_rate": "25%", "effective_date": "March 12, 2025"}}]}, {"pair_id": "conflict_9d4a7bd5fff483c5a328f75d", "claim_ids": ["claim_843e8399a100f28fe9edcb24", "claim_9ca7d5d8e6ba06f32cf9fc63"], "query_ids": ["q_361"], "claims": [{"claim_id": "claim_843e8399a100f28fe9edcb24", "quote": "Proclamation Adjusting Imports of Aluminum and Steel into the United States increases the U.S. tariffs on aluminum, steel and their derivatives from 25% to 50% effective June 4, 2025", "url": "https://www.jdsupra.com/legalnews/u-s-canada-tariffs-timeline-of-key-1897320", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Adjusting Imports of Aluminum and Steel into the United States", "duty_rate": "50%", "effective_date": "June 4, 2025"}}, {"claim_id": "claim_9ca7d5d8e6ba06f32cf9fc63", "quote": "In certain sectors, such as steel and aluminum, existing counter-tariffs will increase from 25 per cent to 50 per cent to match U.S. rates,” Canada’s government said as it vowed to match the U.S. tariffs – effective August 22 – dollar for dollar.", "url": "https://oilprice.com/Metals/Commodities/Canada-Tariffs-Deepen-North-Americas-Steel-and-Aluminum-Squeeze.html", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "50 per cent", "effective_date": "August 22"}}]}, {"pair_id": "conflict_e9696de8963e5320899be115", "claim_ids": ["claim_29e261eb7dbc2f566eee4850", "claim_3f3e4b8ac8a0140a41527a70"], "query_ids": ["q_362"], "claims": [{"claim_id": "claim_29e261eb7dbc2f566eee4850", "quote": "Commercial vehicles, such as sedans, sport utility vehicles, crossover utility vehicles, minivans, cargo vans and light trucks, provided for in heading 9903.94.01, HTSUS, are subject to the Section 232 duties pursuant to the Proclamation.", "url": "https://www.cbp.gov/trade/programs-administration/entry-summary/section-232-additional-faqs-autos", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "Commercial vehicles", "hts_code": "9903.94.01", "duty_rate": "Section 232 duties"}}, {"claim_id": "claim_3f3e4b8ac8a0140a41527a70", "quote": "Light trucks classified in subheadings 8704.21.01, 8704.31.01, 8704.41.00, 8704.51.00, and 8704.60.00 are subject to the duties.", "url": "https://www.cbp.gov/trade/programs-administration/entry-summary/section-232-additional-faqs-autos", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "Light trucks", "hts_code": "8704.21.01, 8704.31.01, 8704.41.00, 8704.51.00, and 8704.60.00"}}]}, {"pair_id": "conflict_cf38c4844749e0c13b3ac88a", "claim_ids": ["claim_60f11b6c8c0a602b93e3bad0", "claim_c031431584d2cf37b232e110"], "query_ids": ["q_362"], "claims": [{"claim_id": "claim_60f11b6c8c0a602b93e3bad0", "quote": "Only auto parts for passenger vehicles and light trucks, as defined by Executive Order 14257, issued April 2, 2025, and subject to Section 232 duties as of May 3, 2025, are not subject to the reciprocal duties effective April 5, 2025, pursuant to heading 9903.01.33, HTSUS.", "url": "https://www.cbp.gov/trade/programs-administration/entry-summary/section-232-additional-faqs-autos", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "Section 232 duties", "legal_authority": "Executive Order 14257", "affected_product": "auto parts for passenger vehicles and light trucks", "hts_code": "9903.01.33", "effective_date": "May 3, 2025"}}, {"claim_id": "claim_c031431584d2cf37b232e110", "quote": "Heading 9903.01.33, HTSUS, exempting products subject to Section 232 from the reciprocal tariffs, applies to auto parts for passenger vehicles and light trucks.", "url": "https://www.cbp.gov/trade/programs-administration/entry-summary/section-232-additional-faqs-autos", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "reciprocal tariffs", "hts_code": "9903.01.33"}}]}, {"pair_id": "conflict_c390ef14227f27e2a3449765", "claim_ids": ["claim_128ca8fb1b7f1fda53cc6c48", "claim_1bcc336dddb3f1b23343432b"], "query_ids": ["q_363"], "claims": [{"claim_id": "claim_128ca8fb1b7f1fda53cc6c48", "quote": "Annex I-B [...] (reduced tariffs for certain steel derivatives until December 31, 2027)", "url": "https://www.congress.gov/crs-product/IN12519", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"expiration_date": "December 31, 2027"}}, {"claim_id": "claim_1bcc336dddb3f1b23343432b", "quote": "10% tariff on full value of derivatives composed of at least 85% U.S.-sourced steel, aluminum, and copper", "url": "https://www.congress.gov/crs-product/IN12519", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "10%"}}]}, {"pair_id": "conflict_3d57c7e3e197cfec23aa133c", "claim_ids": ["claim_372b0eaace850ba53a3cb083", "claim_53932f7008f97665bd846060"], "query_ids": ["q_363"], "claims": [{"claim_id": "claim_372b0eaace850ba53a3cb083", "quote": "IEEPA Reciprocal Tariffs and Section 232\nArticles and derivatives of steel and aluminum subject to Section 232 duties are excluded from the reciprocal tariffs; pursuant to heading 9903.01.33, HTSUS.", "url": "https://www.cbp.gov/trade/programs-administration/entry-summary/232-tariffs-aluminum-and-steel-faqs", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "Section 232", "legal_authority": "heading 9903.01.33, HTSUS"}}, {"claim_id": "claim_53932f7008f97665bd846060", "quote": "The additional duties imposed by headings 9903.01.25, 9903.01.35, 9903.01.39, and 9903.01.43-9903.01.77 shall not apply to derivative aluminum products provided for in headings 9903.85.04, 9903.85.07, 9903.85.08 and 9903.85.09.", "url": "https://www.cbp.gov/trade/programs-administration/entry-summary/232-tariffs-aluminum-and-steel-faqs", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "derivative aluminum products", "chapter_99_code": "9903.85.04, 9903.85.07, 9903.85.08 and 9903.85.09"}}]}]}

